// Auto-generated from client Unity TerrainData assets (TK017*13.tk).
// 257x257 ushort heightmap grid in XZ order: _h[ix * N + iz], scaled by maxY / 65535f.
using System;
using System.Buffers.Binary;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;

namespace GwtEmulator.Server;

public sealed class TerrainHM
{
    public const int N = 257;
    private readonly float _worldSize;
    private readonly float _yScale;
    private readonly ushort[] _h;

    public TerrainHM(float worldSize, float maxY, string gzipBase64)
    {
        _worldSize = worldSize;
        _yScale = maxY / 65535f;
        byte[] compressed = Convert.FromBase64String(gzipBase64);
        byte[] raw = new byte[N * N * 2];
        using (var ms = new MemoryStream(compressed))
        using (var gz = new GZipStream(ms, CompressionMode.Decompress))
        {
            int read = 0;
            while (read < raw.Length)
            {
                int n = gz.Read(raw, read, raw.Length - read);
                if (n <= 0) break;
                read += n;
            }
        }
        _h = new ushort[N * N];
        for (int i = 0; i < _h.Length; i++)
            _h[i] = BinaryPrimitives.ReadUInt16LittleEndian(raw.AsSpan(i * 2, 2));
    }

    public float Surface(float x, float z)
    {
        float fx = Math.Clamp(x / _worldSize, 0f, 1f) * (N - 1);
        float fz = Math.Clamp(z / _worldSize, 0f, 1f) * (N - 1);
        int ix = Math.Clamp((int)MathF.Round(fx), 0, N - 1);
        int iz = Math.Clamp((int)MathF.Round(fz), 0, N - 1);
        return _h[ix * N + iz] * _yScale;
    }

    public float SurfaceBilinear(float x, float z)
    {
        float fx = Math.Clamp(x / _worldSize, 0f, 1f) * (N - 1);
        float fz = Math.Clamp(z / _worldSize, 0f, 1f) * (N - 1);
        int x0 = Math.Min((int)fx, N - 2);
        int z0 = Math.Min((int)fz, N - 2);
        float tx = fx - x0;
        float tz = fz - z0;
        float h00 = _h[x0 * N + z0];
        float h10 = _h[(x0 + 1) * N + z0];
        float h01 = _h[x0 * N + (z0 + 1)];
        float h11 = _h[(x0 + 1) * N + (z0 + 1)];
        float v = h00 * (1f - tx) * (1f - tz)
                + h10 * tx * (1f - tz)
                + h01 * (1f - tx) * tz
                + h11 * tx * tz;
        return v * _yScale;
    }
}

